<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Account list with search, plus the add/edit form and the save action.

import axios from '@nextcloud/axios';
import { t } from '@nextcloud/l10n';
import { generateUrl } from '@nextcloud/router';
import { computed, ref } from 'vue';

import { AccountInformation } from '../format/account';
import { currentDatabase, touch } from '../state/session';
import AccountForm from './AccountForm.vue';

const search = ref('');
const editing = ref<AccountInformation | null>(null);
const originalName = ref<string | null>(null);
const busy = ref(false);
const status = ref('');
/** Bumped whenever the in-memory database changes, to recompute the list. */
const revision = ref(0);

const names = computed<string[]>(() => {
  void revision.value;
  const db = currentDatabase.value;
  if (!db) {
    return [];
  }
  const query = search.value.trim().toLowerCase();
  return db
    .getAccountNames()
    .filter((name) => query === '' || name.toLowerCase().includes(query));
});

/** Edit a copy so Cancel leaves the stored account untouched. */
function select(name: string): void {
  touch();
  const account = currentDatabase.value?.getAccount(name);
  if (account) {
    editing.value = new AccountInformation(
      account.accountName,
      account.userId,
      account.password,
      account.url,
      account.notes,
    );
    originalName.value = account.accountName;
  }
}

function addNew(): void {
  touch();
  editing.value = new AccountInformation();
  originalName.value = null;
}

function cancel(): void {
  editing.value = null;
  originalName.value = null;
}

/** Apply the form to the in-memory database (renaming if the name changed). */
function applyEdit(): void {
  const db = currentDatabase.value;
  const account = editing.value;
  if (!db || !account) {
    return;
  }
  if (originalName.value !== null && originalName.value !== account.accountName) {
    db.deleteAccount(originalName.value);
  }
  db.addAccount(account);
  revision.value++;
  cancel();
}

async function save(): Promise<void> {
  const db = currentDatabase.value;
  if (!db || busy.value) {
    return;
  }
  busy.value = true;
  status.value = '';
  try {
    applyEdit();
    const bytes = await db.save();
    await axios.put(generateUrl('/apps/upm/db'), bytes, {
      headers: { 'Content-Type': 'application/octet-stream' },
    });
    revision.value++;
    status.value = t('upm', 'Saved.');
  } catch {
    status.value = t('upm', 'Could not save the database.');
  } finally {
    busy.value = false;
  }
}

function remove(): void {
  const db = currentDatabase.value;
  const name = originalName.value;
  if (db && name !== null) {
    db.deleteAccount(name);
    revision.value++;
  }
  cancel();
}
</script>

<template>
  <div class="upm-accounts">
    <div style="display: flex; gap: 8px; margin-bottom: 12px">
      <input v-model="search" type="search" :placeholder="t('upm', 'Search')" />
      <button type="button" class="button" @click="addNew">{{ t('upm', 'New account') }}</button>
      <button type="button" class="button primary" :disabled="busy" @click="save">
        {{ busy ? t('upm', 'Saving…') : t('upm', 'Save') }}
      </button>
    </div>

    <p v-if="status">{{ status }}</p>

    <div style="display: flex; gap: 20px; align-items: flex-start">
      <ul style="list-style: none; padding: 0; margin: 0; min-width: 220px">
        <li v-for="name in names" :key="name" style="margin-bottom: 4px">
          <button
            type="button"
            class="button"
            style="width: 100%; text-align: left"
            @click="select(name)"
          >
            {{ name }}
          </button>
        </li>
        <li v-if="names.length === 0">{{ t('upm', 'No accounts yet.') }}</li>
      </ul>

      <AccountForm
        v-if="editing"
        :account="editing"
        @save="save"
        @cancel="cancel"
        @delete="remove"
      />
    </div>
  </div>
</template>
